const salida = [];

for (const [key, value] of Object.entries($binary)) {

  salida.push({
    json: {
      nombreArchivo: value.fileName,
      mimeType: value.mimeType,
      asunto: $json.subject,
      from: $json.from,
      date: $json.date
    },
    binary: {
      attachment: value
    }
  });

}

return salida;

// Obtener los datos que vienen del Google Sheets
const datos = $json;

// Cédula
const cedula = datos["CEDULA"] || datos["CÉDULA"] || "";

// Nombre del cliente
// CO utiliza NOMBRE y PS utiliza CLIENTE 
const cliente =
  datos["NOMBRE"] ||
  datos["CLIENTE "] ||
  datos["CLIENTE"] ||
  "";

// Tipo de contrato
const tipo =
  datos["TIPO CONTRATO"] ||
  datos["TIPO_CONTRATO"] ||
  "";

// Número de contrato
// CO: NUMERO DE CONTRATO
// PS: NUMERO CONTRATO
const numero =
  datos["NUMERO DE CONTRATO"] ||
  datos["NUMERO CONTRATO"] ||
  "";

// Crear nombres de carpetas
const carpetaCliente =
  `${cedula} ${cliente} - AUTO`.trim().toUpperCase();

const carpetaContrato =
  `${tipo} ${numero} ${cliente}`.trim().toUpperCase();

// Mantener todos los datos originales y agregar los nombres
return [
  {
    json: {
      ...datos,
      carpetaCliente,
      carpetaContrato
    }
  }
];

const parts = $json.content?.parts || [];

const texto = parts
   .filter(part => typeof part.text === 'string')
   .map(part => part.text)
   .join('');

const datos = JSON.parse(texto)

return [
  {
    json: datos
  }
];

const encoded = $json.body.message.data;
//Obtiene el texto Base64 que llegó desde Pub/Sub.

const decoded = JSON.parse(
    Buffer.from(encoded, 'base64').toString('utf8')
) 
//"Convierte este Base64 en texto."
return [
  {
    json: decoded
  }
];

const asunto = $json.Subject ?? $json.subject ?? "";

const asuntoNormalizado = asunto.normalize("NFD")
  // Convierte caracteres con tilde a su forma base
  // Ejemplo: "Ó" → "O", "Á" → "A"

 // Elimina los caracteres especiales generados por     normalize()
  // Ejemplo: "Contrató de Obra" → "Contrato de Obra"
  .replace(/[\u0300-\u036f]/g, "")

   // Convierte todo el texto a minúsculas
  // Ejemplo: "CONTRATO DE OBRA" → "contrato de obra"
  .toLowerCase()


    // Elimina todos los espacios en blanco
  // Ejemplo: "contrato de obra" → "contratodeobra"
  .replace(/\s+/g, "");

return {
  ...$json,
  asuntoNormalizado,   //nuevo campo
};

const d = $json;

const idValidacion =
  `VAL-${d.tipo_contrato}-${d.numero_contrato}-${Date.now()}`;

return [
  {
    json: {
      ...d,
      idValidacion
    }
  }
];
